package hu.hazazs.anyconverter;

import java.io.ByteArrayInputStream;
import java.util.Base64;
import javafx.scene.image.Image;

/**
 * The user's black double-arrow graphic, with checkerboard removed to leave
 * transparent pixels. Kept inline so the Windows runnable JAR is self-contained.
 */
final class IconData {

    private static final String PNG =
            "";

    private IconData() {
    }

    static Image loadIcon() {
        return new Image(new ByteArrayInputStream(Base64.getDecoder().decode(PNG)));
    }
}
